import{_ as t,o as r,c as p,a2 as n}from"./chunks/framework.B2QVIpOM.js";const d=JSON.parse('{"title":"圣保罗男女中学 · 年份未注明 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-a36f85cd","school_zh":"圣保罗男女中学","school_en":"—","grade":"s1","year":"unknown","year_label":"年份未注明","type":"interview","title":"圣保罗男女中学 · 年份未注明 · 中一 · 面试","anonymous":true,"source_ids":["C1821-SPCC-U","GUIDE-SPCC","HOT22-SPCC","SPCC-S1-IMAGE-UNKNOWN"],"rounds":["unknown","r1"]},"headers":[],"relativePath":"reports/school-a36f85cd/s1/unknown-interview.md","filePath":"reports/school-a36f85cd/s1/unknown-interview.md"}'),s={name:"reports/school-a36f85cd/s1/unknown-interview.md"};function e(l,o,a,g,c,i){return r(),p("div",null,[...o[0]||(o[0]=[n('<h1 id="圣保罗男女中学-·-年份未注明-·-中一-·-面试" tabindex="-1">圣保罗男女中学 · 年份未注明 · 中一 · 面试 <a class="header-anchor" href="#圣保罗男女中学-·-年份未注明-·-中一-·-面试" aria-label="Permalink to &quot;圣保罗男女中学 · 年份未注明 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-a36f85cd">← 返回圣保罗男女中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c1821-spcc-u" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-spcc-u" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-spcc-u}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>英语：</strong> 英语</p><p><strong>口头完形填充与校对</strong></p><p>有7分钟准备，边读边逐空补一个词，并做选择题、改错及面谈。渔夫故事涉及老人爱钓鱼、卖鱼维生，虽贫穷仍享受生活；第三次撒网发现网很重，最后成功拉起。考生认为完形和校对较难。</p><p><strong>同伴与专题研习</strong></p><p>讨论朋友对自己有好影响还是坏影响、专题研习是否有益；老师按个人资料追问。</p></blockquote><blockquote><p><strong>语文：</strong> 普通话朗读、粤语问答</p><p><strong>阅读准备与语文分析</strong></p><p>有7分钟准备，文章长度约小六课文，亦有百余字版本。普通话朗读，粤语回答主旨、词义、修辞及使用原因，并联系自身经历。</p><p><strong>工人代课故事</strong></p><p>朗读第7至12段；粤语读“崇敬、哆嗦、笑靥、形销骨立”。解释文章主旨、教员哭泣原因，举两处证据说明性格；若自己是学生，会否继续跟随他学习？另问哪句老师的话影响最深、升中或入读后想做什么。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>判断与解释</strong></p><p>判断“15%的男生及30%的女生参加活动，因此全体有45%参加”是否成立并说明理由；检查方程给出的答案，指出错误，再解另一方程。另有应用题和心算。</p><p><strong>图形分割与拼砌</strong></p><p>十字形整体面积4平方厘米，由一条斜线分成A、B两部分，求A面积；用散件尝试拼成平行四边形。另有小六程度的图形分析，两题、不设准备时间、限4分钟。</p></blockquote><blockquote><p><strong>科学：</strong> 语言未注明</p><p><strong>实验现象与方法</strong></p><p>根据维生素C浓度与所需滴数说明现象、提出检测饮品维生素C浓度的方法。另一实验把装置放入热水后，气球A不断胀大，需说出能量名称、解释现象，并预测没有液体C时的情况；液体和完整装置条件未明确。</p><p><strong>空气重量与电路</strong></p><p>比较充气、未充气的气球哪个较重，设计量度气球内空气重量的方法；有不设准备、3分钟作答的反馈。另观察闭合电路实验后回答问题。</p></blockquote><h2 id="record-guide-spcc" tabindex="-1">资料来源：SPCC面試題.pdf <a class="header-anchor" href="#record-guide-spcc" aria-label="Permalink to &quot;资料来源：SPCC面試題.pdf {#record-guide-spcc}&quot;">​</a></h2><p><strong>资料类型：</strong> 机构整理：历年面试题型</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>分站个人面谈</strong></p><p>历史流程约45分钟，以个人面谈为主，不设家长面谈。考生与至少4位不同老师接触，涵盖中文、英文、数学及科学，侧重即场理解、口头回应与思考过程。</p></blockquote><blockquote><p><strong>语文：</strong> 粤语及普通话</p><p><strong>朗读与阅读理解</strong></p><p>阅读文章后回答问题，部分环节给予准备时间，再以普通话作答；另有可选择粤语或普通话朗读的形式，文章可能包含生僻字。</p><p><strong>造句与观点表达</strong></p><ul><li>用粤语以「行行出状元」造句。</li><li>分别用「全神贯注」「心不在焉」造句，并以「经一事长一智」作创意表达。</li><li>评价网上课堂。</li><li>假如拥有时光机，希望前往哪个朝代、见哪位历史人物，并解释原因；部分问答会分别使用粤语和普通话。</li></ul><p><strong>个人经历与角色表达</strong></p><p>介绍自己及就读小学；谈谈学习普通话的困难。具有内地学习经历的考生可能被问及适应香港学校的困难与应对方法。另有将自己想象成改错带并作自我介绍的任务；此前用普通话作答的考生，可能需改用粤语完成。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>文章朗读与理解</strong></p><p>先用数分钟阅读文章，再朗读、补充语法或词汇空缺，并回答外籍老师的问题，包括解释词语及表达对文章的看法。机构整理将部分词汇理解题描述为较难。</p><p><strong>情境追问</strong></p><ul><li>假如可以穿越时空，希望前往何时？</li><li>阅读有关鲨鱼的文章后，回答自己是否敢触摸鲨鱼，并说明理由。</li></ul></blockquote><blockquote><p><strong>数学：</strong> 英语</p><p><strong>口头计算与推理</strong></p><p>约5题，以英文提问，并要求解释思考过程。例题包括：</p><ul><li>已知28 × 48 = 1344，求2.8 × 4.8。</li><li>比较A ÷ (B × C)与A ÷ B × C两种运算表达。</li><li>运用积木、橡皮筋等情境解释逻辑或受力问题。<br> 考核会涉及未必熟悉的情境，除答案外，也关注推理方法。</li></ul></blockquote><blockquote><p><strong>科学：</strong> 英语</p><p><strong>观看与解释</strong></p><p>观看英文科学影片，解释原理，或根据实验及图表回答问题。</p><p><strong>生活现象与实验问题</strong></p><ul><li>不用品尝的方法，如何分辨盐和糖？</li><li>苹果为什么会变色？拌上沙拉酱或放进冰箱后的表现有何不同？如何设计简单实验检验解释？</li><li>怎样冲调阿华田？</li><li>如何分辨生虾和熟虾，虾煮熟后为什么变红？</li><li>乌龟怎样晒太阳？</li><li>两罐可乐，一罐浮起、一罐沉下，可能是什么原因？</li><li>一盒350毫升饮品喝去约三分之一后，向内吹气，为什么液体会流出？</li><li>海龟属于哪一类生物？</li></ul></blockquote><h2 id="record-hot22-spcc" tabindex="-1">资料来源：热门港校面试真题集：中学篇.pdf <a class="header-anchor" href="#record-hot22-spcc" aria-label="Permalink to &quot;资料来源：热门港校面试真题集：中学篇.pdf {#record-hot22-spcc}&quot;">​</a></h2><p><strong>资料类型：</strong> 2022/23机构汇编中的历史面试题</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 中文，含普通话朗读</p><p><strong>阅读赏析</strong></p><p>约7分钟阅读及回答问题，说明文章主旨、道理、词句深层含义及修辞手法，并用普通话朗读其中一段。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>个人与学校</strong></p><p>最喜欢的科目、选择圣保罗男女中学的原因，以及好学校应有什么设施。</p><p><strong>词语与语法</strong></p><p>不供词填空；选择正确词形，例如“The burglar creeped/crept into the house.”中的creeped或crept。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>面积关系</strong></p><p>比较一个长方形被对角线分成的两个三角形的面积关系。另有阴影面积比较：长方形分为上下两行、左右两列，左上与右下涂黑，右上小格画有左下至右上的对角线；问两块阴影面积是否相同并解释。尺寸及额外等长条件未给出。</p><p><strong>质数判断</strong></p><p>判断“15以内质数之和＝1＋2＋3＋5＋7＋11＋13”这一写法是否正确。</p></blockquote><blockquote><p><strong>科学：</strong> 语言未注明</p><p><strong>苹果变色</strong></p><p>解释苹果为什么会变成棕色。</p><p><strong>日照与气球</strong></p><p>A、B均为银色气球，A另外带黑色斑点。比较哪一个较热，并解释阳光照射A的黑色部分时，A爆裂而B没有爆裂的原因。</p><p><strong>透镜与光线</strong></p><p>选择能够借阳光点燃火柴的镜片：A使通过的光线发散，B使光线会聚。解释选择。</p></blockquote><h2 id="record-spcc-s1-image-unknown" tabindex="-1">资料来源：圣保罗男女中一面试.jpg <a class="header-anchor" href="#record-spcc-s1-image-unknown" aria-label="Permalink to &quot;资料来源：圣保罗男女中一面试.jpg {#record-spcc-s1-image-unknown}&quot;">​</a></h2><p><strong>资料类型：</strong> 面试题目整理</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准-2" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-2" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 粤语及普通话</p><p><strong>造句与角色表达</strong></p><p>以粤语分别用「全神贯注」「心不在焉」造句；另以普通话把自己想象成一条改错带，进行自我介绍。</p><p><strong>朗读与理解</strong></p><p>以普通话朗读一段文章，再回答阅读理解问题。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>即场朗读与填充</strong></p><p>朗读老师派发的文章，同时补上缺失的词语。老师随后询问考生对内容的看法，并要求解释文中词语。创意问答例子为：If you were a time traveler, when would you travel to?</p><p><strong>影片理解与小组讨论</strong></p><p>观看没有字幕的英文片段，据此完成一篇英文文章的填充题，再以3至4人小组讨论影片内容。该份面试题整理提醒考生主动参与发言。</p></blockquote><blockquote><p><strong>数学：</strong> 未注明</p><p><strong>限时心算与解释</strong></p><p>3分钟内完成两道数学题，并解释作答思路。</p></blockquote><blockquote><p><strong>科学：</strong> 未注明</p><p><strong>生活现象与分类</strong></p><ul><li>海龟属于哪一类生物？</li><li>除了品尝，还有什么办法分辨盐和糖？</li><li>如何分辨生虾和熟虾？虾煮熟后为什么变红？</li><li>一盒350毫升饮品喝去约三分之一后，向内吹一口气，为什么饮料会涌出？</li></ul></blockquote>',40)])])}const h=t(s,[["render",e]]);export{d as __pageData,h as default};
